from datetime import date, timedelta
from calendar import monthrange


def recur(start: str, rule: str, count: int) -> list[str]:
    first = date.fromisoformat(start)
    parts = rule.split()
    kind = parts[0]
    k = int(parts[1])
    result = []
    weekdays = {
        "MO": 0, "TU": 1, "WE": 2, "TH": 3,
        "FR": 4, "SA": 5, "SU": 6,
    }

    if kind == "DAILY":
        return [
            (first + timedelta(days=i * k)).isoformat()
            for i in range(count)
        ]

    if kind == "WEEKLY":
        days = sorted(weekdays[wd] for wd in parts[2].split(","))
        week = first - timedelta(days=first.weekday())

        while True:
            for wd in days:
                candidate = week + timedelta(days=wd)
                if candidate >= first:
                    result.append(candidate.isoformat())
                    if len(result) == count:
                        return result
            week += timedelta(weeks=k)

    if kind == "MONTHLY":
        month_index = first.year * 12 + first.month - 1
        n = int(parts[2])
        target_wd = weekdays[parts[3]] if len(parts) == 4 else None

        while len(result) < count:
            year, month_zero = divmod(month_index, 12)
            month = month_zero + 1
            last_day = monthrange(year, month)[1]

            if target_wd is None:
                day = last_day if n == -1 else n
            elif n == -1:
                last_wd = date(year, month, last_day).weekday()
                day = last_day - (last_wd - target_wd) % 7
            else:
                first_wd = date(year, month, 1).weekday()
                day = 1 + (target_wd - first_wd) % 7 + 7 * (n - 1)

            if day <= last_day:
                candidate = date(year, month, day)
                if candidate >= first:
                    result.append(candidate.isoformat())

            month_index += k

        return result

    month, day = map(int, parts[2].split("-"))
    year = first.year

    while len(result) < count:
        if day <= monthrange(year, month)[1]:
            candidate = date(year, month, day)
            if candidate >= first:
                result.append(candidate.isoformat())
        year += k

    return result
